module benchmark/solution

import std/json (encode, js, jint)

export func main() -> () ! {IO} {
  let original = {name: "alice", age: 30, role: "engineer"};
  let aged = {original | age: 31};
  let updated = {aged | role: "senior engineer"};
  println("{\"name\": ${encode(js(updated.name))}, \"age\": ${encode(jint(updated.age))}, \"role\": ${encode(js(updated.role))}}")
}
